content:
*,
*::before,
*::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
  font-family: 'Helvetica Neue', Arial, sans-serif;
}

body {
  background-color: #1a1a2e;
  color: #ffffff;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
  overflow: hidden;
}

.app-container {
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  padding: 16px;
  max-width: 480px;
  width: 100%;
  position: relative;
  user-select: none;
  -webkit-user-select: none;
}

.game-title {
  font-size: 1.8rem;
  font-weight: bold;
  margin-bottom: 12px;
  color: #e94560;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.3);
}

.score-board {
  display: flex;
  justify-content: space-between;
  width: 100%;
  max-width: 400px;
  margin-bottom: 12px;
  font-size: 1.1rem;
  font-weight: bold;
  background: #162447;
  padding: 8px 16px;
  border-radius: 8px;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.2);
}

.board {
  display: grid;
  grid-template-columns: repeat(20, 1fr);
  grid-template-rows: repeat(20, 1fr);
  width: 360px;
  height: 360px;
  background-color: #0f3460;
  border: 4px solid #e94560;
  border-radius: 8px;
  box-shadow: 0 8px 16px rgba(0, 0, 0, 0.4);
  position: relative;
  user-select: none;
  -webkit-user-select: none;
}

.cell {
  width: 100%;
  height: 100%;
}

.snake {
  background-color: #4ecc3d;
  border-radius: 4px;
  box-shadow: inset 0 0 4px rgba(0, 0, 0, 0.3);
}

.food {
  background-color: #ff3366;
  border-radius: 50%;
  box-shadow: 0 0 8px #ff3366;
  animation: pulse 1s infinite alternate;
}

@keyframes pulse {
  0% {
    transform: scale(0.85);
  }
  100% {
    transform: scale(1.1);
  }
}

.controls-container {
  display: grid;
  grid-template-areas:
    ". up ."
    "left . right"
    ". down .";
  grid-template-columns: repeat(3, 70px);
  grid-template-rows: repeat(3, 60px);
  gap: 8px;
  margin-top: 20px;
  justify-content: center;
  align-items: center;
  user-select: none;
  -webkit-user-select: none;
}

.control-btn {
  background-color: #1f4068;
  color: #ffffff;
  border: 2px solid #e94560;
  border-radius: 12px;
  font-size: 1.5rem;
  font-weight: bold;
  display: flex;
  justify-content: center;
  align-items: center;
  cursor: pointer;
  box-shadow: 0 4px 6px rgba(0, 0, 0, 0.3);
  transition: background-color 0.1s, transform 0.1s;
  touch-action: manipulation;
}

.control-btn:active {
  background-color: #e94560;
  transform: scale(0.95);
}

.btn-up {
  grid-area: up;
}

.btn-down {
  grid-area: down;
}

.btn-left {
  grid-area: left;
}

.btn-right {
  grid-area: right;
}

.game-over-modal {
  position: absolute;
  top: 0;
  left: 0;
  width: 100%;
  height: 100%;
  background-color: rgba(15, 22, 36, 0.85);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  z-index: 10;
  border-radius: 8px;
  backdrop-filter: blur(4px);
}

.game-over-modal h2 {
  font-size: 2rem;
  color: #ff3366;
  margin-bottom: 8px;
  text-shadow: 0 2px 4px rgba(0, 0, 0, 0.5);
}

.game-over-modal p {
  font-size: 1.2rem;
  margin-bottom: 20px;
  color: #e0e0e0;
}

.btn-primary {
  background-color: #e94560;
  color: #ffffff;
  border: none;
  padding: 12px 28px;
  font-size: 1.1rem;
  font-weight: bold;
  border-radius: 8px;
  cursor: pointer;
  box-shadow: 0 4px 10px rgba(233, 69, 96, 0.4);
  transition: background-color 0.2s, transform 0.1s;
}

.btn-primary:hover {
  background-color: #ff3366;
}

.btn-primary:active {
  transform: scale(0.95);
}

@media (max-width: 400px) {
  .board {
    width: 300px;
    height: 300px;
  }
  .controls-container {
    grid-template-columns: repeat(3, 60px);
    grid-template-rows: repeat(3, 50px);
  }
}

export type Direction = 'UP' | 'DOWN' | 'LEFT' | 'RIGHT';

export interface Position {
  x: number;
  y: number;
}

export type GameState = 'START' | 'PLAYING' | 'PAUSED' | 'GAME_OVER';

import { useMemo } from 'react';
import { Position, GameState } from '../types';

interface SnakeBoardProps {
  snake: Position[];
  food: Position;
  score: number;
  highScore: number;
  gameState: GameState;
  onRestart: () => void;
}

export default function SnakeBoard({
  snake,
  food,
  score,
  highScore,
  gameState,
  onRestart,
}: SnakeBoardProps) {
  const BOARD_SIZE = 20;

  const cells = useMemo(() => {
    const list = [];
    for (let y = 0; y < BOARD_SIZE; y++) {
      for (let x = 0; x < BOARD_SIZE; x++) {
        const isSnake = snake.some((segment) => segment.x === x && segment.y === y);
        const isFood = food.x === x && food.y === y;

        let cellClass = 'cell';
        if (isSnake) cellClass += ' snake';
        if (isFood) cellClass += ' food';

        list.push(<div key={`${x}-${y}`} className={cellClass} />);
      }
    }
    return list;
  }, [snake, food]);

  return (
    <>
      <div className="game-title">スネークゲーム</div>
      <div className="score-board">
        <div>スコア: {score}</div>
        <div>ハイスコア: {highScore}</div>
      </div>
      <div className="board">
        {cells}
        {gameState === 'GAME_OVER' && (
          <div className="game-over-modal">
            <h2>ゲームオーバー</h2>
            <p>スコア: {score}</p>
            <button className="btn-primary" onClick={onRestart}>
              もう一度プレイ
            </button>
          </div>
        )}
        {gameState === 'START' && (
          <div className="game-over-modal">
            <h2>スネークゲーム</h2>
            <p>矢印キーまたは十字ボタンで操作</p>
            <button className="btn-primary" onClick={onRestart}>
              スタート
            </button>
          </div>
        )}
      </div>
    </>
  );
}

import { Direction } from '../types';

interface ControlsProps {
  onDirectionChange: (direction: Direction) => void;
}

export default function Controls({ onDirectionChange }: ControlsProps) {
  const handleTouchStart = (dir: Direction) => (e: React.TouchEvent) => {
    e.preventDefault();
    onDirectionChange(dir);
  };

  return (
    <div className="controls-container">
      <button
        className="control-btn btn-up"
        onClick={() => onDirectionChange('UP')}
        onTouchStart={handleTouchStart('UP')}
        aria-label="上"
      >
        ▲
      </button>
      <button
        className="control-btn btn-left"
        onClick={() => onDirectionChange('LEFT')}
        onTouchStart={handleTouchStart('LEFT')}
        aria-label="左"
      >
        ◀
      </button>
      <button
        className="control-btn btn-right"
        onClick={() => onDirectionChange('RIGHT')}
        onTouchStart={handleTouchStart('RIGHT')}
        aria-label="右"
      >
        ▶
      </button>
      <button
        className="control-btn btn-down"
        onClick={() => onDirectionChange('DOWN')}
        onTouchStart={handleTouchStart('DOWN')}
        aria-label="下"
      >
        ▼
      </button>
    </div>
  );
}

import { useState, useEffect, useCallback, useRef } from 'react';
import { Direction, Position, GameState } from './types';
import SnakeBoard from './components/SnakeBoard';
import Controls from './components/Controls';
import './index.css';

const BOARD_SIZE = 20;
const INITIAL_SNAKE: Position[] = [
  { x: 10, y: 10 },
  { x: 10, y: 11 },
  { x: 10, y: 12 },
];
const INITIAL_FOOD: Position = { x: 5, y: 5 };
const INITIAL_SPEED = 120;

export default function App() {
  const [snake, setSnake] = useState<Position[]>(INITIAL_SNAKE);
  const [food, setFood] = useState<Position>(INITIAL_FOOD);
  const [direction, setDirection] = useState<Direction>('UP');
  const [gameState, setGameState] = useState<GameState>('START');
  const [score, setScore] = useState<number>(0);
  const [highScore, setHighScore] = useState<number>(() => {
    const saved = localStorage.getItem('snake_high_score');
    return saved ? parseInt(saved, 10) : 0;
  });

  const directionRef = useRef<Direction>(direction);
  directionRef.current = direction;

  const generateFood = useCallback((currentSnake: Position[]): Position => {
    while (true) {
      const x = Math.floor(Math.random() * BOARD_SIZE);
      const y = Math.floor(Math.random() * BOARD_SIZE);
      const onSnake = currentSnake.some((seg) => seg.x === x && seg.y === y);
      if (!onSnake) {
        return { x, y };
      }
    }
  }, []);

  const resetGame = () => {
    setSnake(INITIAL_SNAKE);
    setFood(generateFood(INITIAL_SNAKE));
    setDirection('UP');
    directionRef.current = 'UP';
    setScore(0);
    setGameState('PLAYING');
  };

  const handleDirectionChange = useCallback((newDir: Direction) => {
    const current = directionRef.current;
    if (
      (newDir === 'UP' && current !== 'DOWN') ||
      (newDir === 'DOWN' && current !== 'UP') ||
      (newDir === 'LEFT' && current !== 'RIGHT') ||
      (newDir === 'RIGHT' && current !== 'LEFT')
    ) {
      setDirection(newDir);
    }
  }, []);

  useEffect(() => {
    const handleKeyDown = (e: KeyboardEvent) => {
      if (e.key === 'p' || e.key === 'P') {
        setGameState((prev) => {
          if (prev === 'PLAYING') return 'PAUSED';
          if (prev === 'PAUSED') return 'PLAYING';
          return prev;
        });
        return;
      }

      if (gameState !== 'PLAYING') return;

      const keyMap: Record<string, Direction> = {
        ArrowUp: 'UP',
        w: 'UP',
        W: 'UP',
        ArrowDown: 'DOWN',
        s: 'DOWN',
        S: 'DOWN',
        ArrowLeft: 'LEFT',
        a: 'LEFT',
        A: 'LEFT',
        ArrowRight: 'RIGHT',
        d: 'RIGHT',
        D: 'RIGHT',
      };

      if (keyMap[e.key]) {
        handleDirectionChange(keyMap[e.key]);
      }
    };

    window.addEventListener('keydown', handleKeyDown);
    return () => window.removeEventListener('keydown', handleKeyDown);
  }, [gameState, handleDirectionChange]);

  const currentSpeed = Math.max(50, INITIAL_SPEED - Math.floor(score / 50) * 10);

  useEffect(() => {
    if (gameState !== 'PLAYING') return;

    const moveSnake = () => {
      setSnake((prevSnake) => {
        const head = { ...prevSnake[0] };
        const currentDir = directionRef.current;

        if (currentDir === 'UP') head.y -= 1;
        if (currentDir === 'DOWN') head.y += 1;
        if (currentDir === 'LEFT') head.x -= 1;
        if (currentDir === 'RIGHT') head.x += 1;

        // Wall collision
        if (head.x < 0 || head.x >= BOARD_SIZE || head.y < 0 || head.y >= BOARD_SIZE) {
          setGameState('GAME_OVER');
          return prevSnake;
        }

        // Self collision
        if (prevSnake.some((seg) => seg.x === head.x && seg.y === head.y)) {
          setGameState('GAME_OVER');
          return prevSnake;
        }

        const newSnake = [head, ...prevSnake];

        // Eat food
        if (head.x === food.x && head.y === food.y) {
          setScore((prevScore) => {
            const newScore = prevScore + 10;
            if (newScore > highScore) {
              setHighScore(newScore);
              localStorage.setItem('snake_high_score', newScore.toString());
            }
            return newScore;
          });
          setFood(generateFood(newSnake));
        } else {
          newSnake.pop();
        }

        return newSnake;
      });
    };

    const interval = setInterval(moveSnake, currentSpeed);
    return () => clearInterval(interval);
  }, [gameState, food, generateFood, highScore, currentSpeed]);

  return (
    <div className="app-container">
      <SnakeBoard
        snake={snake}
        food={food}
        score={score}
        highScore={highScore}
        gameState={gameState}
        onRestart={resetGame}
      />
      <Controls onDirectionChange={handleDirectionChange} />
    </div>
  );
}
